<?php

declare(strict_types=1);

namespace App\Http\Controllers;

use App\Models\RoomType;
use App\Services\AuditLogger;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
use Illuminate\View\View;

/**
 * Room categories (room types).
 *
 * The slug is generated by the model so public URLs stay stable and readable.
 * A room type with physical rooms attached cannot be deleted.
 */
final class RoomTypeController extends Controller
{
    public function __construct(private readonly AuditLogger $audit) {}

    public function index(Request $request): View
    {
        $search = trim((string) $request->query('search', ''));

        $roomTypes = RoomType::query()
            ->withCount('rooms')
            ->when($search !== '', function ($q) use ($search): void {
                $q->where(function ($inner) use ($search): void {
                    $inner->where('name', 'like', "%{$search}%")
                        ->orWhere('code', 'like', "%{$search}%");
                });
            })
            ->orderBy('base_price')
            ->paginate(20)
            ->withQueryString();

        return view('room-types.index', ['roomTypes' => $roomTypes]);
    }

    public function create(): View
    {
        return view('room-types.create');
    }

    public function store(Request $request): RedirectResponse
    {
        $data = $this->validated($request);

        $roomType = RoomType::query()->create($data);

        $this->audit->success(
            action: 'room-type.create',
            eventType: 'data',
            description: sprintf('Created room type %s (%s).', $roomType->name, $roomType->code),
            subject: $roomType,
            newValues: ['code' => $roomType->code, 'name' => $roomType->name],
        );

        return redirect()->route('room-types.show', $roomType)->with('status', 'Room type created.');
    }

    public function show(RoomType $roomType): View
    {
        $roomType->load('rooms');

        return view('room-types.show', ['roomType' => $roomType]);
    }

    public function edit(RoomType $roomType): View
    {
        return view('room-types.edit', ['roomType' => $roomType]);
    }

    public function update(Request $request, RoomType $roomType): RedirectResponse
    {
        $data = $this->validated($request, $roomType);

        $roomType->update($data);

        $this->audit->success(
            action: 'room-type.update',
            eventType: 'data',
            description: sprintf('Updated room type %s (%s).', $roomType->name, $roomType->code),
            subject: $roomType,
            newValues: ['code' => $roomType->code, 'name' => $roomType->name],
        );

        return redirect()->route('room-types.show', $roomType)->with('status', 'Room type updated.');
    }

    public function destroy(RoomType $roomType): RedirectResponse
    {
        if ($roomType->rooms()->exists()) {
            return back()->with('error', 'This room type still has rooms assigned. Move or delete those rooms first.');
        }

        $name = $roomType->name;
        $roomType->delete();

        $this->audit->success(
            action: 'room-type.delete',
            eventType: 'data',
            description: sprintf('Deleted room type %s.', $name),
        );

        return redirect()->route('room-types.index')->with('status', 'Room type '.$name.' deleted.');
    }

    /**
     * @return array<string, mixed>
     */
    private function validated(Request $request, ?RoomType $roomType = null): array
    {
        $data = $request->validate([
            'code' => [
                'required', 'string', 'max:20',
                Rule::unique('room_types', 'code')->ignore($roomType?->getKey()),
            ],
            'name' => ['required', 'string', 'max:80'],
            'description' => ['nullable', 'string', 'max:2000'],
            'bed_type' => ['required', 'string', 'max:60'],
            'capacity' => ['required', 'integer', 'min:1', 'max:20'],
            'base_price' => ['required', 'numeric', 'min:0', 'max:1000000'],
            'amenities' => ['nullable', 'string', 'max:1000'],
            'image_url' => ['nullable', 'string', 'max:500'],
            'is_active' => ['nullable', 'boolean'],
        ]);

        $data['amenities'] = $this->parseAmenities($request->input('amenities'));
        $data['is_active'] = $request->boolean('is_active');

        return $data;
    }

    /**
     * Turn a comma/newline separated amenity string into a clean array.
     *
     * @return array<int, string>
     */
    private function parseAmenities(?string $raw): array
    {
        if ($raw === null || trim($raw) === '') {
            return [];
        }

        $parts = preg_split('/[\r\n,]+/', $raw) ?: [];

        return array_values(array_filter(
            array_map(static fn (string $item): string => trim($item), $parts),
            static fn (string $item): bool => $item !== '',
        ));
    }
}
